old_function = "function money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}"
new_function = """function money(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v)||0)}
let latestPricing=null;
function escapeQuote(value){return String(value??'').replace(/[&<>\\\"']/g,match=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[match]))}
function pricingQuoteMarkup(){if(!latestPricing)return '';const p=latestPricing;const photo=p.photoData?`<img class=\\\"quote-photo\\\" src=\\\"${p.photoData}\\\" alt=\\\"Referência visual do produto\\\"/>`:'';return `<article class=\\\"quote-print\\\"><div style=\\\"display:flex;justify-content:space-between;gap:18px;align-items:flex-start\\\"><div><div style=\\\"font-size:11px;letter-spacing:.12em;color:#8b5cf6;font-weight:700\\\">AGENTE DE MARKETING DIGITAL</div><h1>Orçamento de ${escapeQuote(p.name)}</h1><div class=\\\"quote-meta\\\">Estimativa preparada em ${escapeQuote(p.date)} · válida para revisão comercial</div></div>${photo}</div><div class=\\\"quote-grid\\\"><div class=\\\"quote-card\\\"><strong>Preço mínimo</strong><b>${money(p.minimum)}</b><div style=\\\"font-size:11px;color:#63708a;margin-top:5px\\\">Cobre custos e taxas</div></div><div class=\\\"quote-card\\\" style=\\\"border-color:#8b5cf6;background:#faf7ff\\\"><strong>Preço recomendado</strong><b>${money(p.suggested)}</b><div style=\\\"font-size:11px;color:#63708a;margin-top:5px\\\">Margem informada</div></div><div class=\\\"quote-card\\\"><strong>Preço premium</strong><b>${money(p.premium)}</b><div style=\\\"font-size:11px;color:#63708a;margin-top:5px\\\">Margem ampliada</div></div></div><h2>Memória de cálculo</h2><table><tr><td>Mão de obra (${p.hours} h × ${money(p.rate)})</td><td>${money(p.labor)}</td></tr><tr><td>Materiais e insumos</td><td>${money(p.materials)}</td></tr><tr><td>Embalagem e frete</td><td>${money(p.packaging)}</td></tr><tr><td>Custos indiretos e outros</td><td>${money(p.overhead)}</td></tr><tr><td>Custo base</td><td>${money(p.base)}</td></tr><tr><td>Taxas · Margem desejada</td><td>${p.feesPct.toFixed(1)}% · ${p.marginPct.toFixed(1)}%</td></tr></table><h2>Análise visual assistida</h2><pre>${escapeQuote(p.visual||'Nenhuma observação visual disponível.')}</pre><div class=\\\"quote-note\\\"><strong>Estimativa revisável:</strong> este material é uma sugestão de preço baseada nos dados informados e em observações visuais auxiliares. A aprovação final, negociação e envio ao cliente dependem de decisão humana.</div></article>`}
function exportPricingPdf(){if(!latestPricing){alert('Calcule uma precificação antes de exportar.');return}const win=window.open('','_blank');if(!win){alert('Permita pop-ups para exportar o PDF.');return}win.document.write(`<!doctype html><html lang=\\\"pt-BR\\\"><head><meta charset=\\\"utf-8\\\"><title>Orçamento — ${escapeQuote(latestPricing.name)}</title><link rel=\\\"preconnect\\\" href=\\\"https://fonts.googleapis.com\\\"><link href=\\\"https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&family=Syne:wght@600;700&display=swap\\\" rel=\\\"stylesheet\\\"><style>@page{size:A4;margin:12mm}body{margin:0;background:#fff}button{position:fixed;right:24px;top:20px;border:0;border-radius:8px;background:#6d3df5;color:#fff;padding:11px 16px;font-weight:700;cursor:pointer}@media print{button{display:none}}</style></head><body>${pricingQuoteMarkup()}<button onclick=\\\"window.print()\\\">Salvar como PDF / Imprimir</button><script>window.onload=()=>setTimeout(()=>window.print(),450)<\\/script></body></html>`);win.document.close()}
function svgQuoteText(text,x,y,size,weight='400',color='#25324a'){return `<text x=\\\"${x}\\\" y=\\\"${y}\\\" font-family=\\\"Arial, sans-serif\\\" font-size=\\\"${size}\\\" font-weight=\\\"${weight}\\\" fill=\\\"${color}\\\">${escapeQuote(text)}</text>`}
function exportPricingImage(){if(!latestPricing){alert('Calcule uma precificação antes de exportar.');return}const p=latestPricing,w=1400,h=1060;let svg=`<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"${w}\\\" height=\\\"${h}\\\" viewBox=\\\"0 0 ${w} ${h}\\\"><rect width=\\\"100%\\\" height=\\\"100%\\\" fill=\\\"#080b13\\\"/><rect x=\\\"40\\\" y=\\\"40\\\" width=\\\"1320\\\" height=\\\"980\\\" rx=\\\"26\\\" fill=\\\"#101827\\\" stroke=\\\"#283552\\\"/><circle cx=\\\"1240\\\" cy=\\\"115\\\" r=\\\"180\\\" fill=\\\"#6d3df5\\\" opacity=\\\".13\\\"/>${svgQuoteText('AGENTE DE MARKETING DIGITAL',90,105,19,'700','#a990ff')}${svgQuoteText(`Orçamento de ${p.name}`,90,155,38,'700','#f4f1ff')}${svgQuoteText(`Estimativa revisável · ${p.date}`,90,190,17,'400','#96a2ba')}`;const cards=[['MÍNIMO',p.minimum,'#22c8de'],['RECOMENDADO',p.suggested,'#a990ff'],['PREMIUM',p.premium,'#ef78c8']];cards.forEach((c,i)=>{const x=90+i*410;svg+=`<rect x=\\\"${x}\\\" y=\\\"235\\\" width=\\\"370\\\" height=\\\"142\\\" rx=\\\"16\\\" fill=\\\"#151f32\\\" stroke=\\\"${c[2]}\\\" stroke-opacity=\\\".55\\\"/>`+svgQuoteText(c[0],x+25,272,15,'700','#9aa8c2')+svgQuoteText(money(c[1]),x+25,325,32,'700','#ffffff')});svg+=svgQuoteText('MEMÓRIA DE CÁLCULO',90,438,16,'700','#a990ff');const rows=[`Mão de obra: ${p.hours} h × ${money(p.rate)} = ${money(p.labor)}`,`Materiais e insumos: ${money(p.materials)}`,`Embalagem e frete: ${money(p.packaging)}`,`Custos indiretos: ${money(p.overhead)}`,`Custo base: ${money(p.base)}`,`Taxas: ${p.feesPct.toFixed(1)}% · Margem: ${p.marginPct.toFixed(1)}%`];rows.forEach((row,i)=>{svg+=svgQuoteText(row,90,480+i*34,18,'400','#c3ccdc')});svg+=svgQuoteText('ANÁLISE VISUAL ASSISTIDA',760,438,16,'700','#a990ff');const visualLines=String(p.visual||'Indisponível').split(/\\n/).slice(0,10);visualLines.forEach((row,i)=>{svg+=svgQuoteText(row.slice(0,48),760,480+i*28,16,'400','#c3ccdc')});svg+=`<rect x=\\\"90\\\" y=\\\"745\\\" width=\\\"1220\\\" height=\\\"150\\\" rx=\\\"14\\\" fill=\\\"#0d3440\\\" stroke=\\\"#22c8de\\\" stroke-opacity=\\\".4\\\"/>`+svgQuoteText('ESTIMATIVA REVISÁVEL',120,790,17,'700','#55e1ee')+svgQuoteText('Revise custos, posicionamento e negociação antes de enviar ao cliente.',120,830,18,'400','#d5f7fa')+svgQuoteText('Nenhuma publicação ou ação externa é executada automaticamente.',120,865,18,'400','#d5f7fa')+'</svg>';const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);URL.revokeObjectURL(url);const a=document.createElement('a');a.download=`orcamento-${(p.name||'produto').toLowerCase().replace(/[^a-z0-9]+/gi,'-')}.png`;a.href=canvas.toDataURL('image/png');a.click()};img.src=url}
"""
if old_function not in s:
    raise SystemExit('money function anchor not found')
s = s.replace(old_function, new_function, 1)

old_tail = "const final=breakdown+'\\n\\nANÁLISE VISUAL ASSISTIDA\\n'+visual;result.textContent=final;saveHistory('Precificação',`Preço sugerido — ${name}`,`Foto: ${pricePhotoName||'não enviada'}; Horas: ${hours}; Valor/hora: ${money(rate)}; Materiais: ${money(materials)}; Embalagem: ${money(packaging)}; Indiretos: ${money(overhead)}; Taxas: ${(fees*100).toFixed(1)}%; Margem: ${(margin*100).toFixed(1)}%`,final,'Foto + cálculo',null,{photoReference:pricePhotoData?{name:pricePhotoName,dataUrl:pricePhotoData}:null,scenarios:{minimum,suggested,premium}})}"
new_tail = "const final=breakdown+'\\n\\nANÁLISE VISUAL ASSISTIDA\\n'+visual;result.textContent=final;latestPricing={name,hours,rate,materials,packaging,overhead,feesPct:fees*100,marginPct:margin*100,labor,base,minimum,suggested,premium,visual,photoData:pricePhotoData,date:new Date().toLocaleDateString('pt-BR')};document.getElementById('price-export-actions').hidden=false;saveHistory('Precificação',`Preço sugerido — ${name}`,`Foto: ${pricePhotoName||'não enviada'}; Horas: ${hours}; Valor/hora: ${money(rate)}; Materiais: ${money(materials)}; Embalagem: ${money(packaging)}; Indiretos: ${money(overhead)}; Taxas: ${(fees*100).toFixed(1)}%; Margem: ${(margin*100).toFixed(1)}%`,final,'Foto + cálculo',null,{photoReference:pricePhotoData?{name:pricePhotoName,dataUrl:pricePhotoData}:null,scenarios:{minimum,suggested,premium}})}"
if old_tail not in s:
    raise SystemExit('calculatePrice tail anchor not found')
